// K1 Katsastus: Muster booking + live station directory.
// n8n Code node body (runOnceForAllItems). Called by the agent tools and the builder webhook.
// The DIRECTORY placeholder below is filled by k1-agent-v2-build.py from design/k1-fresh/data/k1-directory.json.
//
// Two Muster systems, deliberately separated:
//   staging    (chain 91): the only place a booking is ever created, changed or cancelled.
//   production (chain 5):  read-only calendar/products/prices, used to describe stations that are not bookable here yet.
const STAGING = 'https://staging-booking-api.muster.fi/v3/91'
// Staging calls go through a random proxy from this pool (filled in at build time; an empty pool means direct).
// Mode 'fallback' (default): the n8n server IP is whitelisted at Muster, so the first attempt goes direct and a proxy is only used when a retry is needed.
// Mode 'always': every staging call goes through a proxy.
const STAGING_PROXY_MODE = "fallback"
const STAGING_PROXIES = [{"protocol":"http","host":"159.148.236.168","port":6374,"auth":{"username":"REDACTED","password":"REDACTED"}},{"protocol":"http","host":"31.98.7.50","port":6228,"auth":{"username":"REDACTED","password":"REDACTED"}},{"protocol":"http","host":"31.98.7.58","port":6236,"auth":{"username":"REDACTED","password":"REDACTED"}},{"protocol":"http","host":"46.203.41.122","port":5623,"auth":{"username":"REDACTED","password":"REDACTED"}},{"protocol":"http","host":"179.61.172.26","port":6577,"auth":{"username":"REDACTED","password":"REDACTED"}},{"protocol":"http","host":"46.203.15.103","port":7104,"auth":{"username":"REDACTED","password":"REDACTED"}},{"protocol":"http","host":"31.98.8.76","port":5754,"auth":{"username":"REDACTED","password":"REDACTED"}},{"protocol":"http","host":"82.23.62.244","port":7997,"auth":{"username":"REDACTED","password":"REDACTED"}},{"protocol":"http","host":"46.203.86.15","port":5515,"auth":{"username":"REDACTED","password":"REDACTED"}},{"protocol":"http","host":"179.61.172.119","port":6670,"auth":{"username":"REDACTED","password":"REDACTED"}},{"protocol":"http","host":"195.40.128.249","port":6969,"auth":{"username":"REDACTED","password":"REDACTED"}},{"protocol":"http","host":"195.40.133.145","port":6365,"auth":{"username":"REDACTED","password":"REDACTED"}},{"protocol":"http","host":"195.40.129.208","port":6929,"auth":{"username":"REDACTED","password":"REDACTED"}},{"protocol":"http","host":"212.212.19.47","port":6198,"auth":{"username":"REDACTED","password":"REDACTED"}},{"protocol":"http","host":"195.40.128.161","port":6881,"auth":{"username":"REDACTED","password":"REDACTED"}},{"protocol":"http","host":"212.212.19.110","port":6261,"auth":{"username":"REDACTED","password":"REDACTED"}},{"protocol":"http","host":"195.40.138.41","port":5761,"auth":{"username":"REDACTED","password":"REDACTED"}},{"protocol":"http","host":"195.40.138.90","port":5810,"auth":{"username":"REDACTED","password":"REDACTED"}},{"protocol":"http","host":"87.86.25.92","port":5243,"auth":{"username":"REDACTED","password":"REDACTED"}},{"protocol":"http","host":"195.40.128.194","port":6914,"auth":{"username":"REDACTED","password":"REDACTED"}}]
let lastProxy = null
const pickProxy = () => {
  const pool = STAGING_PROXIES.length > 1 ? STAGING_PROXIES.filter((proxy) => proxy !== lastProxy) : STAGING_PROXIES
  lastProxy = pool[Math.floor(Math.random() * pool.length)]
  return lastProxy
}
const request = (options, attempt = 0) => this.helpers.httpRequest.call(this, STAGING_PROXIES.length && String(options.url).startsWith(STAGING) && (STAGING_PROXY_MODE === 'always' || attempt > 0) ? { ...options, proxy: pickProxy() } : options)
