const strip = (fragment) => String(fragment).replace(/<[^>]+>/g, ' ').replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/&euro;/g, '€').replace(/\s+/g, ' ').trim()
function parsePage(html) {
