const incoming = $input.all().map((item) => item.json)
const only = incoming.length === 1 ? incoming[0] : null
const rows = Array.isArray(only) ? only : incoming.filter((row) => row && row.groupId)
const groups = [...new Set(rows.map((row) => row.groupId).filter(Boolean))]
const request = (options) => this.helpers.httpRequest.call(this, options)
const cancelled = []
for (const groupId of groups) {
  try {
    await request({ method: 'DELETE', url: 'https://staging-booking-api.muster.fi/v3/91/Reservations/' + groupId + '?sendConfirmation=false', json: true, proxy: PROXIES[Math.floor(Math.random() * PROXIES.length)] })
    cancelled.push({ groupId, ok: true })
  } catch (error) {
    cancelled.push({ groupId, ok: false })
  }
}
return [{ json: { cancelled } }]

