const muster = $('Muster').first().json
const saved = $input.first().json
const raw = saved && (saved.message || saved.error || saved.hint)
const value = typeof saved === 'number' ? saved : saved && (saved.updated ?? saved.count ?? saved.data ?? saved.body ?? saved.result ?? saved.value ?? saved.json)
let updated = NaN
try {
  const parsed = typeof value === 'string' ? JSON.parse(value) : value
  updated = Number(Array.isArray(parsed) ? parsed[0]?.mark_booking_cancelled : parsed && typeof parsed === 'object' ? parsed.mark_booking_cancelled : parsed)
} catch (error) {}
if (raw || !Number.isInteger(updated) || updated < 1) {
  return [{ json: {
    ...muster,
    ok: false,
    success: false,
    step: 'mark_booking_cancelled',
    error: raw ? String(typeof raw === 'object' ? raw.message || raw.description || 'save failed' : raw).slice(0, 400) : 'Booking cancelled in Muster, but the stored booking was not marked cancelled.',
  } }]
}
return [{ json: { ...muster, recorded: true, updated } }]

const original = $('When called by the agent').first().json
const rows = $input.all().flatMap((item) => (Array.isArray(item.json) ? item.json : [item.json]))
const failed = rows.some((row) => row && (row.message || row.error || row.code) && !row.groupId)
const tail = (value) => String(value || '').replace(/\D/g, '').slice(-9)
const caller = tail(original.phone)
const mine = rows.filter((row) => caller && row && row.groupId && row.status === 'confirmed' && tail(row.phone) === caller)
const details = mine.map((row) => ({ groupId: row.groupId, reservationUid: row.reservationUid, customerUid: row.customerUid, bookingNumber: row.bookingNumber, stationId: row.stationId, stationName: row.stationName, plate: row.plate, startsAt: row.startsAt, productIds: row.productIds || [] }))
return [{ json: { ...original, require_owner: true, owned_bookings: mine.map((row) => row.groupId), owned_details: details, owner_lookup_failed: failed } }]
